from huggingface_hub.utils import filter_repo_objects

from app.publish import SUMMARIES_REPO, publish_run, publish_summary


class RecordingApi:
    def __init__(self):
        self.calls = []

    def upload_file(self, **kwargs):
        self.calls.append(kwargs)
        return SimpleNamespace(commit_url="https://huggingface.co/datasets/acme-ml/run-summaries/commit/abc")

    def create_repo(self, **kwargs):
        self.calls.append(("create_repo", kwargs))

    def upload_folder(self, **kwargs):
        self.calls.append(("upload_folder", kwargs))


def test_publish_run_creates_private_repo_then_uploads_folder_to_root(tmp_path):
    api = RecordingApi()

    publish_run(tmp_path, "acme-ml/run-0007", api=api)

    (create, create_kwargs), (upload, upload_kwargs) = api.calls
    assert create == "create_repo" and upload == "upload_folder"
    assert create_kwargs == {"repo_id": "acme-ml/run-0007", "repo_type": "dataset", "private": True, "exist_ok": True}
    assert upload_kwargs["repo_id"] == "acme-ml/run-0007" and upload_kwargs["repo_type"] == "dataset"
    assert upload_kwargs["folder_path"] == tmp_path
    assert upload_kwargs.get("path_in_repo") in (None, "")

    paths = ["ckpt/step-100/model.safetensors", "ckpt/partial.tmp", "wandb/run-1/files/log.txt", "metrics.json"]
    kept = list(filter_repo_objects(paths, ignore_patterns=upload_kwargs["ignore_patterns"]))
    assert kept == ["ckpt/step-100/model.safetensors", "metrics.json"]

